CREATE FUNCTION cmd_validate_linguistics_decipher() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE task cmd_actor_task_receipt%ROWTYPE; BEGIN SELECT * INTO STRICT task FROM cmd_actor_task_receipt WHERE command_id=NEW.task_command_id; IF task.actor_id<>NEW.actor_id OR task.skill_rule_id<>(SELECT skill_rule_id FROM rule_linguistics_mechanic) OR task.check_total<>NEW.check_total OR task.effect<>NEW.effect OR task.succeeded<>NEW.general_meaning_recovered OR (NEW.language_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM camp_language l JOIN actor_actor a ON a.campaign_id=l.campaign_id WHERE l.language_id=NEW.language_id AND a.actor_id=NEW.actor_id)) THEN RAISE EXCEPTION 'Linguistics decipher receipt mismatch'; END IF; RETURN NEW; END $$;
CREATE TRIGGER cmd_linguistics_decipher_valid BEFORE INSERT ON cmd_linguistics_decipher_receipt FOR EACH ROW EXECUTE FUNCTION cmd_validate_linguistics_decipher();
